/** Cells across a face: what the object can be ruled into, finest to coarsest. */
export const INFINITY_CUBE_RULINGS: readonly number[] =
  [...new Set(INFINITY_CUBE_DESIGNS.map(d => d.cells))].sort((a, b) => a - b);

/** Seeds that need no search, at a ruling. */
export function infinityCubeDesigns(cells: number): readonly StoredDesign[] {
  return INFINITY_CUBE_DESIGNS.filter(design => design.cells === cells);
}

/** The one for this ruling and seed, if it was worth keeping. */
export function infinityCubeDesign(cells: number, seed: number): StoredDesign | null {
  return INFINITY_CUBE_DESIGNS.find(d => d.cells === cells && d.seed === seed) ?? null;
}
